\label{thm:jump}
Fix $R\ge1000$ and real $|t|\le50/R$. Then
$\lambda_p>\lambda_q>\log4$, and the following hold.
\begin{enumerate}[label=(\roman*)]
\item At $t=0$, we have
$\dim_{\mathrm H}\mu_{F_{R,0}}=\log2/\lambda_p+\log2/\lambda_q$.
\item For $t\ne0$, we have
$\dim_{\mathrm H}\mu_{F_{R,t}}=2\log2/\lambda_2(R,t)>\mathcal D_{\mathrm{P}}(F_{R,t})$.
\end{enumerate}
Moreover, $\lambda_1(R,t)=\lambda_p$ and
$\lambda_2(R,t)\to\lambda_q$ as $t\to0$, and hence
\begin{equation}\label{eq:dimension-jump}
 \lim_{\substack{0\neq t \to 0}}\dim_{\mathrm H}\mu_{F_{R,t}}
 -\dim_{\mathrm H}\mu_{F_{R,0}}
 =\log2\left(\frac1{\lambda_q}-\frac1{\lambda_p}\right)>0.
\end{equation}

\label{def:spreading}
For a fixed translation $h\in[0,1)^2$, we say that $\nu_{\hat x}$ is \emph{spreading at $x$ with
window $\ell$, error $\epsilon$, and depth $n$}
if
\begin{equation}\label{eq:spreading-definition}
 \#\left\{0\le j\le n-\ell:
 \nu_{\hat x}(\mathcal D_{j+\ell}^h(x))
 \le\tfrac12\nu_{\hat x}(\mathcal D_j^h(x))\right\}
 \ge(1-\epsilon)n.
\end{equation}

\label{prop:local-growth}
Assume that 
\hyperref[hyp:H]{(H)} holds and that the fast direction is history-dependent. If $\gamma_f>0$, then $\gamma_t\ge1$.

\label{prop:rectangles}
For $(\nu\otimes\beta_S\otimes\mathcal L^4)$-almost every
$(x,s,{\mathbf h})$, we have
\begin{equation}\label{eq:rectangle-bound}
 \liminf_{k\to\infty}
 \frac{\log\nu(\mathcal R_{k,s}^{\mathbf h}(x))}{-k\log2}
 \ge7\gamma_f+8\gamma_t.
\end{equation}
Moreover, for every $\epsilon>0$ and $0<\alpha<1$, there exist
an integer $N$ and a measurable set
$\mathcal S\subset(K\cap U)\times S\times[0,1)^4$
with $(\nu\otimes\beta_S\otimes\mathcal L^4)(\mathcal S)
\ge1-\alpha$ such that the following bounds hold at every
$(x,s,\mathbf h)\in\mathcal S$:

\begin{enumerate}[label=(\roman*),leftmargin=*]
\item
\emph{(Spatial ball estimate)}
$r^{D+\epsilon}\le\nu(B(x,r))\le r^{D-\epsilon}$
for every $0<r<2^{-N}$;
\item
\emph{(Transverse ball estimate)}
$r^{\gamma_t+\epsilon}\le\zeta_s(B(p_sx,r))
\le r^{\gamma_t-\epsilon}$
for every $0<r<2^{-N}$;
\item
\emph{(Product partition estimate)}
$\nu(\mathcal R_{k,s}^{\mathbf h}(x))
\le2^{-k(7\gamma_f+8\gamma_t-\epsilon)}$
for every $k\ge N$.
\end{enumerate}
